"use client";

import { Switch as SwitchPrimitive } from "@base-ui/react/switch";

import { cn } from "@/lib/utils";
import { controlChecked, focusRing, optionTrack } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Mallow Switch: a lilac track with a white knob when off, and a violet track with the same white knob when on. */
function Switch({ className, ...props }: WithClassName<SwitchPrimitive.Root.Props>) {
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      className={cn(
        "group/switch peer inline-flex h-7 w-12 shrink-0 cursor-pointer items-center rounded-full p-0.5",
        optionTrack,
        "inset-ring-1 inset-ring-foreground/50 data-[checked]:inset-ring-transparent",
        controlChecked,
        "transition-[box-shadow,background-color] duration-base ease-(--ease-out)",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className={cn(
          "pointer-events-none block size-6 rounded-full",
          "bg-card shadow-(--shadow-thumb)",
          "data-[checked]:translate-x-5 data-[unchecked]:translate-x-0 rtl:data-[checked]:-translate-x-5",
          "origin-left data-[checked]:origin-right rtl:origin-right rtl:data-[checked]:origin-left transition-[translate,scale,transform-origin,background-color,box-shadow] duration-[260ms,140ms,0ms,150ms,150ms] delay-[0ms,0ms,140ms,0ms,0ms] ease-out motion-safe:group-active/switch:scale-x-[1.18] motion-reduce:transition-none",
        )}
      />
    </SwitchPrimitive.Root>
  );
}
Switch.displayName = "Switch";

export { Switch };
